    registerAUser: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /**
                     * @description User first name.
                     * @example Augusto
                     */
                    name: string;
                    /**
                     * @description User last name.
                     * @example Restrepo
                     */
                    surname: string;
                    /**
                     * @description Email address. Must be unique. Must be a valid email address.
                     * @example augusto@example.com
                     */
                    email: string;
                    /**
                     * @description Password. Must meet the default strength rules and be confirmed via passwordConfirmation. The value and <code>passwordConfirmation</code> must match.
                     * @example Str0ngP@ss!
                     */
                    password: string;
                    /**
                     * @description Confirmation of the new password. Must match the password field. Note: camelCase, not the Laravel-default password_confirmation.
                     * @example NewStr0ng!
                     */
                    passwordConfirmation: string;
                    /**
                     * @description Optional. Role to assign at registration. One of: coffeeshop, specialist, user.
                     * @example coffeeshop
                     * @enum {string}
                     */
                    role?: "coffeeshop" | "specialist" | "user";
                };
            };
        };
        responses: {
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: {
                            /** @example 01M35F5RX4ADGC3CSDXXYB08DC */
                            ulid?: string;
                            /** @example Laura */
                            name?: string;
                            /** @example Gómez */
                            surname?: string;
                            /** @example laura@tazavera.test */
                            email?: string;
                            /** @example coffeeshop */
                            role?: string;
                        };
                        /** @example Profile created. */
                        message?: string;
                    };
                };
            };
        };
    };
